{{ stage('Clone Table') }}
CREATE OR REPLACE TABLE {{ nodeMetadata.desiredLocation }}`{{ nodeMetadata.oldName }}_COALESCE_INTERNAL_TABLE`
  COPY {{ nodeMetadata.oldLocation }}`{{ nodeMetadata.oldName }}`

{{ stage('Delete Column') }}
ALTER TABLE {{ nodeMetadata.desiredLocation }}`{{ nodeMetadata.oldName }}_COALESCE_INTERNAL_TABLE`
{% for col in nodeMetadata.deletedColumns %}
  DROP COLUMN IF EXISTS `{{ col.name }}`{% if not loop.last %},{% endif %}
{% endfor %};

{{ stage('Add Column') }}
ALTER TABLE {{ nodeMetadata.desiredLocation }}`{{ nodeMetadata.oldName }}_COALESCE_INTERNAL_TABLE`
{% for col in nodeMetadata.addedColumns %}
    ADD COLUMN
      `{{col.name}}` {{col.dataType}} {%- if not col.nullable %} NOT NULL{% endif %}
      {%- if col.defaultValue | length > 0 %} DEFAULT {{ col.defaultValue }}{% endif %}
      {%- if col.description | length > 0 %} OPTIONS(description='{{ col.description | escape }}'){% endif %}
      {%- if not loop.last -%},{% endif %}
  {% endfor %};

{{ stage('Replace Table')}}
CREATE OR REPLACE TABLE {{ nodeMetadata.desiredLocation }}`{{ nodeMetadata.operationName }}`  
 COPY {{ nodeMetadata.desiredLocation }}`{{ nodeMetadata.oldName }}_COALESCE_INTERNAL_TABLE`;

